} from 'react'
import { createPortal } from 'react-dom'

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  open?: boolean
}

export type DialogPortalProps = {
  children: ReactNode
  container?: HTMLElement | null
  forceMount?: boolean
}

export type DialogOverlayProps = HTMLAttributes<HTMLDivElement> & {
  forceMount?: boolean
}

export type DialogContentProps = HTMLAttributes<HTMLDivElement> & {
  forceMount?: boolean
  initialFocusRef?: MutableRefObject<HTMLElement | null>
}

export type DialogTitleProps = HTMLAttributes<HTMLHeadingElement>
export type DialogDescriptionProps = HTMLAttributes<HTMLParagraphElement>
export type DialogTriggerProps = ButtonHTMLAttributes<HTMLButtonElement>
export type DialogCloseProps = ButtonHTMLAttributes<HTMLButtonElement>

type LegacyDialogProps = {
  children: ReactNode
  description: string
  title: string
  triggerLabel: string
}

type DialogContextValue = {
  contentId: string
  descriptionId: string
  open: boolean
  setOpen: (open: boolean) => void
  titleId: string
  triggerRef: MutableRefObject<HTMLButtonElement | null>
}

const DialogContext = createContext<DialogContextValue | null>(null)

const canUseDOM = typeof window !== 'undefined' && typeof document !== 'undefined'

type DialogStackRecord = {
  contentNode: HTMLElement
  document: Document
  id: string
  restoreFocusTo: HTMLElement | null
}

const openDialogs: DialogStackRecord[] = []
const hiddenSiblings = new WeakMap<Document, Map<HTMLElement, string | null>>()

function assignRef<T>(ref: Ref<T> | undefined, value: T) {
  if (typeof ref === 'function') {
    ref(value)
    return
  }

  if (ref) {
    ;(ref as MutableRefObject<T>).current = value
  }
}

function composeEventHandlers<EventType extends { defaultPrevented: boolean }>(
  theirHandler: ((event: EventType) => void) | undefined,
  ourHandler: (event: EventType) => void,
) {
  return (event: EventType) => {
    theirHandler?.(event)
    if (!event.defaultPrevented) {
      ourHandler(event)
    }
  }
}

function getFocusableElements(container: HTMLElement) {
  const selector = [
    'a[href]',
    'button:not([disabled])',
    'input:not([disabled])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])',
  ].join(',')

  return Array.from(container.querySelectorAll<HTMLElement>(selector)).filter((element) => {
    if (element.hidden) {
      return false
    }

    if (element.getAttribute('aria-hidden') === 'true') {
      return false
    }

    return element.tabIndex >= 0
  })
}

function restoreAriaHidden(documentNode: Document) {
  const tracked = hiddenSiblings.get(documentNode)
  if (!tracked) {
    return
  }

  for (const [element, previousValue] of tracked) {
    if (previousValue === null) {
      element.removeAttribute('aria-hidden')
    } else {
      element.setAttribute('aria-hidden', previousValue)
    }
  }

  tracked.clear()
}

function syncAriaHidden(documentNode: Document) {
  restoreAriaHidden(documentNode)

  const topDialog = [...openDialogs].reverse().find((record) => record.document === documentNode)
  if (!topDialog) {
    return
  }

  const tracked = new Map<HTMLElement, string | null>()
  hiddenSiblings.set(documentNode, tracked)

  for (const element of Array.from(documentNode.body.children)) {
    if (element.contains(topDialog.contentNode)) {
      continue
    }

    tracked.set(element as HTMLElement, element.getAttribute('aria-hidden'))
    element.setAttribute('aria-hidden', 'true')
  }
}

function registerDialog(record: DialogStackRecord) {
  openDialogs.push(record)
  syncAriaHidden(record.document)
}

function unregisterDialog(id: string) {
  const recordIndex = openDialogs.findIndex((record) => record.id === id)
  if (recordIndex === -1) {
    return null
  }

  const [record] = openDialogs.splice(recordIndex, 1)
  syncAriaHidden(record.document)
  return record
}

function isTopDialog(id: string) {
  const topDialog = openDialogs.at(-1)
  return topDialog?.id === id
}

function useDialogContext(componentName: string) {
  const context = useContext(DialogContext)

  if (!context) {
    throw new Error(`${componentName} must be used within DialogRoot.`)
  }

  return context
}

function useControllableOpenState({
  defaultOpen = false,
  onOpenChange,
  open: openProp,
}: Pick<DialogRootProps, 'defaultOpen' | 'onOpenChange' | 'open'>) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = openProp !== undefined
  const open = isControlled ? openProp : uncontrolledOpen

  const setOpen = (nextOpen: boolean) => {
    if (!isControlled) {
      setUncontrolledOpen(nextOpen)
    }

    onOpenChange?.(nextOpen)
  }

  return [open, setOpen] as const
}

export function DialogRoot({ children, defaultOpen, onOpenChange, open: openProp }: DialogRootProps) {
  const [open, setOpen] = useControllableOpenState({ defaultOpen, onOpenChange, open: openProp })
  const triggerRef = useRef<HTMLButtonElement | null>(null)
  const contentId = useId()
  const titleId = useId()
  const descriptionId = useId()

  return (
    <DialogContext.Provider
      value={{ contentId, descriptionId, open, setOpen, titleId, triggerRef }}
    >
      {children}
    </DialogContext.Provider>
  )
}

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(function DialogTrigger(
  { onClick, type = 'button', ...props },
  forwardedRef,
) {
  const context = useDialogContext('DialogTrigger')

  return (
    <button
      {...props}
      ref={(node) => {
        context.triggerRef.current = node
        assignRef(forwardedRef, node)
      }}
      aria-controls={context.contentId}
      aria-expanded={context.open}
      aria-haspopup="dialog"
      data-state={context.open ? 'open' : 'closed'}
      onClick={composeEventHandlers(onClick, (event) => {
        context.triggerRef.current = event.currentTarget
        context.setOpen(true)
      })}
      type={type}
    />
  )
})

export function DialogPortal({ children, container, forceMount = false }: DialogPortalProps) {
  const context = useDialogContext('DialogPortal')
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  if (!forceMount && !context.open) {
    return null
  }

  if (!canUseDOM || !mounted) {
    return <>{children}</>
  }

  return createPortal(children, container ?? document.body)
}

export const DialogOverlay = forwardRef<HTMLDivElement, DialogOverlayProps>(function DialogOverlay(
  { forceMount = false, onClick, ...props },
  forwardedRef,
) {
  const context = useDialogContext('DialogOverlay')

  if (!forceMount && !context.open) {
    return null
  }

  return (
    <div
      {...props}
      ref={forwardedRef}
      data-state={context.open ? 'open' : 'closed'}
      onClick={composeEventHandlers(onClick, (event) => {
        if (event.target === event.currentTarget) {
          context.setOpen(false)
        }
      })}
    />
  )
})

